@if(count($education))<section class="section"><h2 class="section-title">Education</h2>@foreach($education as $e) @php($field=$e['field_of_study']??$e['field']??'') <div class="entry"><table class="row"><tr><td class="entry-title">{{ $e['degree']??'' }}{{ !empty($e['degree'])&&$field?' in ':'' }}{{ $field }}</td><td class="date">{{ $dateRange($e) }}</td></tr></table><div class="subtitle">{{ $e['university']??$e['institution']??'' }}</div>@if(!empty($e['description']))<p class="description">{{ $e['description'] }}</p>@endif @if($gpa)<div class="muted">GPA: {{ $gpa }}</div>@endif</div>@endforeach</section>@endif
@if(count($skillGroups))<section class="section"><h2 class="section-title">Technical Skills</h2><table class="skills">@foreach($skillGroups as $category=>$items)<tr><td class="skill-category">{{ $category }}</td><td class="skill-list">{{ implode(', ',$items) }}</td></tr>@endforeach</table></section>@endif
@if(count($projects))<section class="section"><h2 class="section-title">Projects</h2>@foreach($projects as $p)<div class="entry"><div class="entry-title">{{ $p['name']??$p['title']??'' }}</div>@if(!empty($p['technologies']))<div class="subtitle">{{ is_array($p['technologies'])?implode(', ',$p['technologies']):$p['technologies'] }}</div>@endif @if(!empty($p['description']))<p class="description">{{ $p['description'] }}</p>@endif @if(!empty($p['url'])||!empty($p['link']))<div class="muted">{{ $p['url']??$p['link'] }}</div>@endif</div>@endforeach</section>@endif
@if(count($languages)||count($certificates)||count($activities)||count($achievements))<section class="section"><h2 class="section-title">Additional Information</h2>
