@foreach(['Activities'=>$activities,'Achievements'=>$achievements] as $label=>$items)@if(count($items))<div class="extra"><div class="extra-title">{{ $label }}</div>@foreach($items as $x)<div>@if(is_array($x))<strong>{{ $x['name']??$x['title']??'' }}</strong>@if(!empty($x['description'])) - {{ $x['description'] }}@endif @else{{ $x }}@endif</div>@endforeach</div>@endif @endforeach
</section>@endif
